1	//! Cache revalidation for ETag and git strategies.
2	
3	use anyhow::Result;
4	
5	use super::{CacheEntry, CacheStore, ValidationResult};
6	use crate::registry::fetch::{GitFetcher, HttpFetcher};
7	
8	/// Performs cache revalidation using ETag or git checking.
9	pub struct CacheRevalidator<'a> {
10	    store: &'a CacheStore,
11	    http: HttpFetcher,
12	    git: GitFetcher,
13	}
14	
15	/// Result of revalidation.
16	#[derive(Debug)]
17	pub enum RevalidationResult {
18	    /// Content unchanged, cache extended.
19	    Unchanged,
20	    /// Content changed, new content available.
21	    Updated(String),
22	    /// Revalidation failed (fallback to cache or error).
23	    Failed(String),
24	}
25	
26	impl<'a> CacheRevalidator<'a> {
27	    /// Create a new revalidator.
28	    pub fn new(store: &'a CacheStore, git_clone_dir: impl Into<std::path::PathBuf>) -> Self {
29	        Self {
30	            store,
31	            http: HttpFetcher::new(),
32	            git: GitFetcher::new(git_clone_dir),
33	        }
34	    }
35	
36	    /// Revalidate an entry using its ETag.
37	    pub fn revalidate_etag(
38	        &self,
39	        url: &str,
40	        entry: &mut CacheEntry,
41	        new_ttl_seconds: u64,
42	    ) -> Result<RevalidationResult> {
43	        let etag = entry.metadata.etag.as_deref();
44	
45	        match self.http.fetch_if_changed(url, etag)? {
46	            None => {
47	                // 304 Not Modified - extend TTL
48	                entry.metadata.expires_at =
49	                    chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
50	                self.store.update(entry)?;
51	                Ok(RevalidationResult::Unchanged)
52	            }
53	            Some(response) => {
54	                // Content changed - update cache
55	                let content_path = self
56	                    .store
57	                    .content_path(&entry.source_id, &entry.template_name);
58	                std::fs::write(&content_path, &response.content)?;
59	
60	                entry.metadata.etag = response.etag;
61	                entry.metadata.size_bytes = response.content.len() as u64;
62	                entry.metadata.cached_at = chrono::Utc::now();
63	                entry.metadata.expires_at =
64	                    chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
65	                self.store.update(entry)?;
66	
67	                Ok(RevalidationResult::Updated(response.content))
68	            }
69	        }
70	    }
71	
72	    /// Revalidate an entry using git commit comparison.
73	    pub fn revalidate_git(
74	        &self,
75	        url: &str,
76	        git_ref: Option<&str>,
77	        entry: &mut CacheEntry,
78	        new_ttl_seconds: u64,
79	    ) -> Result<RevalidationResult> {
80	        let current_sha = match &entry.metadata.commit_sha {
81	            Some(sha) => sha.clone(),
82	            None => {
83	                // No SHA to compare, must re-fetch
84	                return self.fetch_git(url, git_ref, entry, new_ttl_seconds);
85	            }
86	        };
87	
88	        let has_updates = self.git.has_updates(url, git_ref, &current_sha)?;
89	
90	        if has_updates {
91	            self.fetch_git(url, git_ref, entry, new_ttl_seconds)
92	        } else {
93	            // No updates - extend TTL
94	            entry.metadata.expires_at =
95	                chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
96	            self.store.update(entry)?;
97	            Ok(RevalidationResult::Unchanged)
98	        }
99	    }
100	
101	    /// Fetch from git and update the cache entry.
102	    fn fetch_git(
103	        &self,
104	        url: &str,
105	        git_ref: Option<&str>,
106	        entry: &mut CacheEntry,
107	        new_ttl_seconds: u64,
108	    ) -> Result<RevalidationResult> {
109	        let result = self.git.fetch(url, git_ref)?;
110	
111	        // Copy content from cloned repo to cache
112	        let content_path = self
113	            .store
114	            .content_path(&entry.source_id, &entry.template_name);
115	
116	        // For git sources, we store a marker that the content is at the git path
117	        let content = format!("git-path:{}", result.local_path.display());
118	        std::fs::write(&content_path, &content)?;
119	
120	        entry.metadata.commit_sha = Some(result.commit_sha);
121	        entry.metadata.cached_at = chrono::Utc::now();
122	        entry.metadata.expires_at =
123	            chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
124	        self.store.update(entry)?;
125	
126	        Ok(RevalidationResult::Updated(content))
127	    }
128	}
129	
130	/// Check if a validation result needs revalidation.
131	pub fn needs_revalidation(result: &ValidationResult) -> bool {
132	    matches!(result, ValidationResult::NeedsRevalidation)
133	}
134	
135	#[cfg(test)]
136	mod tests {
137	    use super::*;
138	    use httpmock::prelude::*;
139	    use tempfile::TempDir;
140	
141	    #[test]
142	    fn needs_revalidation_check() {
143	        assert!(!needs_revalidation(&ValidationResult::Fresh));
144	        assert!(!needs_revalidation(&ValidationResult::Expired));
145	        assert!(needs_revalidation(&ValidationResult::NeedsRevalidation));
146	        assert!(!needs_revalidation(&ValidationResult::NotFound));
147	    }
148	
149	    #[test]
150	    fn revalidator_creation() {
151	        let temp = TempDir::new().unwrap();
152	        let store = CacheStore::new(temp.path());
153	
154	        let git_dir = temp.path().join("git");
155	        let _revalidator = CacheRevalidator::new(&store, git_dir);
156	    }
157	
158	    #[test]
159	    fn revalidation_result_variants() {
160	        let unchanged = RevalidationResult::Unchanged;
161	        let updated = RevalidationResult::Updated("new content".to_string());
162	        let failed = RevalidationResult::Failed("network error".to_string());
163	
164	        // Just check we can pattern match
165	        match unchanged {
166	            RevalidationResult::Unchanged => {}
167	            _ => panic!("expected Unchanged"),
168	        }
169	
170	        match updated {
171	            RevalidationResult::Updated(content) => assert_eq!(content, "new content"),
172	            _ => panic!("expected Updated"),
173	        }
174	
175	        match failed {
176	            RevalidationResult::Failed(msg) => assert_eq!(msg, "network error"),
177	            _ => panic!("expected Failed"),
178	        }
179	    }
180	
181	    // --- Mock HTTP revalidation tests ---
182	
183	    #[test]
184	    fn etag_revalidation_unchanged_on_304() {
185	        let server = MockServer::start();
186	
187	        let mock = server.mock(|when, then| {
188	            when.method(GET)
189	                .path("/template.yml")
190	                .header("If-None-Match", "\"etag-v1\"");
191	            then.status(304);
192	        });
193	
194	        let temp = TempDir::new().unwrap();
195	        let store = CacheStore::new(temp.path());
196	        let git_dir = temp.path().join("git");
197	        let revalidator = CacheRevalidator::new(&store, git_dir);
198	
199	        // Create an expired cache entry with an etag
200	        let mut entry = store
201	            .store("http:test", "template", "old content", 0)
202	            .unwrap();
203	        entry.metadata.etag = Some("\"etag-v1\"".to_string());
204	        store.update(&entry).unwrap();
205	
206	        let result = revalidator
207	            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
208	            .unwrap();
209	
210	        mock.assert();
211	        assert!(matches!(result, RevalidationResult::Unchanged));
212	        // TTL should be extended
213	        assert!(!entry.is_expired());
214	    }
215	
216	    #[test]
217	    fn etag_revalidation_updated_on_200() {
218	        let server = MockServer::start();
219	
220	        server.mock(|when, then| {
221	            when.method(GET).path("/template.yml");
222	            then.status(200)
223	                .header("ETag", "\"etag-v2\"")
224	                .body("new content");
225	        });
226	
227	        let temp = TempDir::new().unwrap();
228	        let store = CacheStore::new(temp.path());
229	        let git_dir = temp.path().join("git");
230	        let revalidator = CacheRevalidator::new(&store, git_dir);
231	
232	        // Create an expired cache entry with an old etag
233	        let mut entry = store
234	            .store("http:test", "template", "old content", 0)
235	            .unwrap();
236	        entry.metadata.etag = Some("\"etag-v1\"".to_string());
237	        store.update(&entry).unwrap();
238	
239	        let result = revalidator
240	            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
241	            .unwrap();
242	
243	        match result {
244	            RevalidationResult::Updated(content) => {
245	                assert_eq!(content, "new content");
246	            }
247	            other => panic!("Expected Updated, got {:?}", other),
248	        }
249	
250	        // ETag should be updated
251	        assert_eq!(entry.metadata.etag, Some("\"etag-v2\"".to_string()));
252	        // TTL should be extended
253	        assert!(!entry.is_expired());
254	    }
255	
256	    #[test]
257	    fn etag_revalidation_updates_cached_content_on_disk() {
258	        let server = MockServer::start();
259	
260	        server.mock(|when, then| {
261	            when.method(GET).path("/template.yml");
262	            then.status(200)
263	                .header("ETag", "\"etag-v2\"")
264	                .body("updated content on disk");
265	        });
266	
267	        let temp = TempDir::new().unwrap();
268	        let store = CacheStore::new(temp.path());
269	        let git_dir = temp.path().join("git");
270	        let revalidator = CacheRevalidator::new(&store, git_dir);
271	
272	        let mut entry = store
273	            .store("http:test", "template", "old content", 0)
274	            .unwrap();
275	        entry.metadata.etag = Some("\"etag-v1\"".to_string());
276	        store.update(&entry).unwrap();
277	
278	        revalidator
279	            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
280	            .unwrap();
281	
282	        // Verify content on disk is updated
283	        let content = store.read_content(&entry).unwrap();
284	        assert_eq!(content, "updated content on disk");
285	    }
286	}
