84	    /// Create a failure result.
85	    pub fn failure(
86	        exit_code: Option<i32>,
87	        stdout: String,
88	        stderr: String,
89	        duration: Duration,
90	    ) -> Self {
91	        Self {
92	            exit_code,
93	            stdout,
94	            stderr,
95	            duration,
96	            success: false,
97	        }
98	    }
