1	//! Requirement evaluation logic.
2	//!
3	//! `RequirementEvaluator` determines whether a single requirement is
4	//! satisfied by running checks against the current system state. It is
5	//! stateless (no cache) and used by `GapChecker` as a delegate.
6	
7	use crate::requirements::probe::EnvironmentProbe;
8	use crate::requirements::registry::{RequirementCheck, RequirementRegistry};
9	use crate::requirements::status::RequirementStatus;
10	use std::path::{Path, PathBuf};
11	use std::process::Command;
12	
13	/// Evaluates individual requirements against system state.
14	///
15	/// Stateless: holds references to the registry, probe, and project root,
16	/// but does not cache results. Caching is the responsibility of
17	/// [`super::GapChecker`].
18	pub(super) struct RequirementEvaluator<'a> {
19	    pub(super) registry: &'a RequirementRegistry,
20	    pub(super) probe: &'a EnvironmentProbe,
21	    pub(super) project_root: PathBuf,
22	}
23	
24	impl<'a> RequirementEvaluator<'a> {
25	    /// Evaluate a requirement by name, returning its current status.
26	    pub(super) fn evaluate(&self, requirement: &str) -> RequirementStatus {
27	        let Some(req) = self.registry.get(requirement) else {
28	            return RequirementStatus::Unknown;
29	        };
30	
31	        for check in &req.checks {
32	            if let Some(status) = self.evaluate_check(check, req) {
33	                return status;
34	            }
35	        }
36	
37	        // No check matched -- Missing
38	        RequirementStatus::Missing {
39	            install_template: req.install_template.clone(),
40	            install_hint: req.install_hint.clone(),
41	        }
42	    }
43	
44	    fn evaluate_check(
45	        &self,
46	        check: &RequirementCheck,
47	        req: &crate::requirements::registry::Requirement,
48	    ) -> Option<RequirementStatus> {
49	        match check {
50	            RequirementCheck::CommandSucceeds(cmd) => {
51	                if self.run_command_succeeds(cmd) {
52	                    Some(RequirementStatus::Satisfied)
53	                } else {
54	                    None
55	                }
56	            }
57	            RequirementCheck::FileExists(path) => {
58	                let full_path = if Path::new(path).is_absolute() {
59	                    PathBuf::from(path)
60	                } else {
61	                    self.project_root.join(path)
62	                };
63	                if full_path.exists() {
64	                    Some(RequirementStatus::Satisfied)
65	                } else {
66	                    None
67	                }
68	            }
69	            RequirementCheck::ServiceReachable(cmd) => {
70	                if self.run_command_succeeds(cmd) {
71	                    Some(RequirementStatus::Satisfied)
72	                } else {
73	                    Some(RequirementStatus::ServiceDown {
74	                        binary_present: self.check_binary_present(cmd),
75	                        install_template: req.install_template.clone(),
76	                        start_command: None,
77	                        start_hint: req
78	                            .install_hint
79	                            .clone()
80	                            .unwrap_or_else(|| format!("Start the {} service", req.name)),
81	                    })
82	                }
83	            }
84	            RequirementCheck::ManagedCommand {
85	                command: tool,
86	                managed_path_patterns,
87	                system_path_patterns,
88	                version_file,
89	            } => self.evaluate_managed_command(
90	                tool,
91	                managed_path_patterns,
92	                system_path_patterns,
93	                version_file.as_deref(),
94	                req,
95	            ),
96	            RequirementCheck::Any(sub_checks) => {
97	                for sub in sub_checks {
98	                    if let Some(status) = self.evaluate_check(sub, req) {
99	                        if status.is_satisfied() || status.can_proceed() {
100	                            return Some(status);
101	                        }
102	                    }
103	                }
104	                None
105	            }
106	        }
107	    }
108	
109	    fn evaluate_managed_command(
110	        &self,
111	        tool: &str,
112	        managed_path_patterns: &[String],
113	        system_path_patterns: &[String],
114	        version_file: Option<&str>,
115	        req: &crate::requirements::registry::Requirement,
116	    ) -> Option<RequirementStatus> {
117	        let full_path = self.probe.full_path();
118	
119	        // Resolve where the tool is on the full (augmented) PATH
120	        if let Some(resolved) =
121	            crate::requirements::probe::resolve_tool_path(tool, full_path.as_slice())
122	        {
123	            let path_str = resolved.to_string_lossy().to_string();
124	
125	            // Check 1: Managed path patterns -> Satisfied
126	            for pattern in managed_path_patterns {
127	                if path_str.contains(pattern) {
128	                    return Some(RequirementStatus::Satisfied);
129	                }
130	            }
131	
132	            // Check 2: Inactive manager with version file
133	            if let Some(vf) = version_file {
134	                if self.project_root.join(vf).exists()
135	                    || self.project_root.join(".tool-versions").exists()
136	                {
137	                    let original_path = crate::requirements::probe::parse_system_path();
138	                    let on_original =
139	                        crate::requirements::probe::resolve_tool_path(tool, &original_path);
140	                    if on_original.is_none() {
141	                        for mgr in self.probe.inactive_managers() {
142	                            let mgr_binary = format!("{}/", mgr.name);
143	                            if path_str.contains(&mgr_binary)
144	                                || resolved.starts_with(&mgr.install_path)
145	                            {
146	                                return Some(RequirementStatus::Inactive {
147	                                    manager: mgr.name.clone(),
148	                                    binary_path: resolved,
149	                                    activation_hint: mgr.activation.clone(),
150	                                });
151	                            }
152	                        }
153	                    }
154	                }
155	            }
156	
157	            // Check 3: System path patterns -> SystemOnly
158	            for pattern in system_path_patterns {
159	                if path_str.contains(pattern) || path_str.starts_with(pattern) {
160	                    return Some(RequirementStatus::SystemOnly {
161	                        path: resolved,
162	                        install_template: req.install_template.clone(),
163	                        warning: format!(
164	                            "System {} detected at {}. Consider using a version manager.",
165	                            tool, path_str
166	                        ),
167	                    });
168	                }
169	            }
170	
171	            // Check 4: Found on PATH, none of the above -> Satisfied
172	            return Some(RequirementStatus::Satisfied);
173	        }
174	
175	        // Check 5: Nothing found -> None (let caller handle as Missing)
176	        None
177	    }
178	
179	    fn run_command_succeeds(&self, cmd: &str) -> bool {
180	        let full_path_str = self
181	            .probe
182	            .full_path()
183	            .iter()
184	            .map(|p| p.to_string_lossy().to_string())
185	            .collect::<Vec<_>>()
186	            .join(":");
187	
188	        Command::new("sh")
189	            .arg("-c")
190	            .arg(cmd)
191	            .env("PATH", &full_path_str)
192	            .stdout(std::process::Stdio::null())
193	            .stderr(std::process::Stdio::null())
194	            .status()
195	            .is_ok_and(|s| s.success())
196	    }
197	
198	    fn check_binary_present(&self, service_cmd: &str) -> bool {
199	        let binary = service_cmd.split_whitespace().next().unwrap_or("");
200	        if binary.is_empty() {
201	            return false;
202	        }
203	        let full_path = self.probe.full_path();
204	        crate::requirements::probe::resolve_tool_path(binary, full_path.as_slice()).is_some()
205	    }
206	}
