641	
642	        // The fetcher's simple cache returns whatever is in the file,
643	        // so it will return the corrupted content. This is by design:
644	        // RemoteFetcher's cache is a simple file-based cache without
645	        // integrity checks. The caller (ExtendsResolver) handles
646	        // YAML parse errors.
647	        let content = fetcher.fetch(&url).unwrap();
648	        assert_eq!(content, "garbage\x00\x01\x02not yaml");
649	        // Still only 1 server hit (cache was returned, even if corrupted)
650	        mock.assert_calls(1);
