1	//! Platform abstractions replacing lightweight external crates.
2	//!
3	//! Provides cross-platform implementations for:
4	//! - Directory discovery (replaces `dirs`)
5	//! - URL percent-encoding (replaces `urlencoding`)
6	//! - Opening URLs in the default browser (replaces `open`)
7	//! - Finding executables on PATH (replaces `which`)
8	//! - Cryptographic random byte generation (replaces `getrandom`)
9	//! - File glob pattern matching (replaces `glob`)
10	
11	use std::path::{Path, PathBuf};
12	
13	// === Directory discovery ===
14	
15	/// Returns the user's home directory.
16	pub fn home_dir() -> Option<PathBuf> {
17	    if cfg!(windows) {
18	        std::env::var_os("USERPROFILE").map(PathBuf::from)
19	    } else {
20	        std::env::var_os("HOME").map(PathBuf::from)
21	    }
22	}
23	
24	/// Returns the platform-specific cache directory.
25	///
26	/// - macOS: `$HOME/Library/Caches`
27	/// - Linux: `$XDG_CACHE_HOME` or `$HOME/.cache`
28	/// - Windows: `%LOCALAPPDATA%`
29	pub fn cache_dir() -> Option<PathBuf> {
30	    if cfg!(target_os = "macos") {
31	        home_dir().map(|h| h.join("Library/Caches"))
32	    } else if cfg!(windows) {
33	        std::env::var_os("LOCALAPPDATA").map(PathBuf::from)
34	    } else {
35	        // Linux / other Unix
36	        std::env::var_os("XDG_CACHE_HOME")
37	            .map(PathBuf::from)
38	            .or_else(|| home_dir().map(|h| h.join(".cache")))
39	    }
40	}
41	
42	/// Returns the platform-specific data directory.
43	///
44	/// - macOS: `$HOME/Library/Application Support`
45	/// - Linux: `$XDG_DATA_HOME` or `$HOME/.local/share`
46	/// - Windows: `%APPDATA%`
47	pub fn data_dir() -> Option<PathBuf> {
48	    if cfg!(target_os = "macos") {
49	        home_dir().map(|h| h.join("Library/Application Support"))
50	    } else if cfg!(windows) {
51	        std::env::var_os("APPDATA").map(PathBuf::from)
52	    } else {
53	        std::env::var_os("XDG_DATA_HOME")
54	            .map(PathBuf::from)
55	            .or_else(|| home_dir().map(|h| h.join(".local/share")))
56	    }
57	}
58	
59	/// Returns the platform-specific local data directory.
60	///
61	/// Same as [`data_dir`] on macOS and Linux.
62	/// On Windows, returns `%LOCALAPPDATA%`.
63	pub fn data_local_dir() -> Option<PathBuf> {
64	    if cfg!(windows) {
65	        std::env::var_os("LOCALAPPDATA").map(PathBuf::from)
66	    } else {
67	        data_dir()
68	    }
69	}
70	
71	/// Returns the platform-specific documents directory.
72	pub fn document_dir() -> Option<PathBuf> {
73	    home_dir().map(|h| h.join("Documents"))
74	}
75	
76	// === URL percent-encoding ===
77	
78	/// Percent-encode a string for use in URLs.
79	///
80	/// Encodes all characters except unreserved characters
81	/// (A-Z, a-z, 0-9, `-`, `_`, `.`, `~`) as defined in RFC 3986.
82	pub fn percent_encode(input: &str) -> String {
83	    let mut encoded = String::with_capacity(input.len());
84	    for byte in input.bytes() {
85	        match byte {
86	            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
87	                encoded.push(byte as char);
88	            }
89	            _ => {
90	                encoded.push('%');
91	                encoded.push(HEX_CHARS[(byte >> 4) as usize] as char);
92	                encoded.push(HEX_CHARS[(byte & 0x0F) as usize] as char);
93	            }
94	        }
95	    }
96	    encoded
97	}
98	
99	const HEX_CHARS: &[u8; 16] = b"0123456789ABCDEF";
100	
101	/// Decode a percent-encoded string.
102	pub fn percent_decode(input: &str) -> Result<String, std::string::FromUtf8Error> {
103	    let mut bytes = Vec::with_capacity(input.len());
104	    let mut chars = input.bytes();
105	    while let Some(b) = chars.next() {
106	        if b == b'%' {
107	            let hi = chars.next().and_then(from_hex_digit);
108	            let lo = chars.next().and_then(from_hex_digit);
109	            match (hi, lo) {
110	                (Some(h), Some(l)) => bytes.push((h << 4) | l),
111	                _ => {
112	                    // Malformed percent encoding — pass through literally
113	                    bytes.push(b'%');
114	                }
115	            }
116	        } else if b == b'+' {
117	            bytes.push(b' ');
118	        } else {
119	            bytes.push(b);
120	        }
121	    }
122	    String::from_utf8(bytes)
123	}
124	
125	fn from_hex_digit(b: u8) -> Option<u8> {
126	    match b {
127	        b'0'..=b'9' => Some(b - b'0'),
128	        b'a'..=b'f' => Some(b - b'a' + 10),
129	        b'A'..=b'F' => Some(b - b'A' + 10),
130	        _ => None,
131	    }
132	}
133	
134	// === Browser/URL opening ===
135	
136	/// Open a URL in the platform's default browser or handler.
137	pub fn open_in_browser(url: &str) -> std::io::Result<()> {
138	    let (cmd, args): (&str, &[&str]) = if cfg!(target_os = "macos") {
139	        ("open", &[url])
140	    } else if cfg!(windows) {
141	        ("cmd", &["/C", "start", "", url])
142	    } else {
143	        ("xdg-open", &[url])
144	    };
145	
146	    std::process::Command::new(cmd)
147	        .args(args)
148	        .stdin(std::process::Stdio::null())
149	        .stdout(std::process::Stdio::null())
150	        .stderr(std::process::Stdio::null())
151	        .status()
152	        .map(|_| ())
153	}
154	
155	// === PATH lookup ===
156	
157	/// Check whether an executable exists on the system PATH.
158	pub fn find_on_path(binary: &str) -> Option<PathBuf> {
159	    let path_var = std::env::var_os("PATH")?;
160	    let separator = if cfg!(windows) { ';' } else { ':' };
161	
162	    for dir in path_var.to_string_lossy().split(separator) {
163	        let candidate = Path::new(dir).join(binary);
164	        if candidate.is_file() {
165	            return Some(candidate);
166	        }
167	        // On Windows, also check with common extensions
168	        if cfg!(windows) {
169	            for ext in &[".exe", ".cmd", ".bat", ".com"] {
170	                let with_ext = Path::new(dir).join(format!("{}{}", binary, ext));
171	                if with_ext.is_file() {
172	                    return Some(with_ext);
173	                }
174	            }
175	        }
176	    }
177	    None
178	}
179	
180	// === Random bytes ===
181	
182	/// Fill a buffer with cryptographically secure random bytes.
183	#[cfg(unix)]
184	pub fn random_bytes(buf: &mut [u8]) {
185	    use std::io::Read;
186	    std::fs::File::open("/dev/urandom")
187	        .and_then(|mut f| f.read_exact(buf))
188	        .expect("Failed to read /dev/urandom");
189	}
190	
191	/// Fill a buffer with cryptographically secure random bytes.
192	#[cfg(windows)]
193	pub fn random_bytes(buf: &mut [u8]) {
194	    extern "system" {
195	        fn BCryptGenRandom(
196	            hAlgorithm: *mut std::ffi::c_void,
197	            pbBuffer: *mut u8,
198	            cbBuffer: u32,
199	            dwFlags: u32,
200	        ) -> i32;
201	    }
202	    const BCRYPT_USE_SYSTEM_PREFERRED_RNG: u32 = 0x00000002;
203	    let status = unsafe {
204	        BCryptGenRandom(
205	            std::ptr::null_mut(),
206	            buf.as_mut_ptr(),
207	            buf.len() as u32,
208	            BCRYPT_USE_SYSTEM_PREFERRED_RNG,
209	        )
210	    };
211	    assert!(status >= 0, "BCryptGenRandom failed with status {status}");
212	}
213	
214	// === Glob pattern matching ===
215	
216	/// Match files against a glob pattern and return matching paths.
217	///
218	/// Supports `*` (any non-separator chars), `**` (recursive directory match),
219	/// and `?` (single char). The pattern should be an absolute path with glob
220	/// characters (e.g., `/path/to/project/*.rb`).
221	pub fn glob(pattern: &str) -> Result<Vec<PathBuf>, String> {
222	    let pattern = pattern.replace('\\', "/");
223	
224	    // Find where the first wildcard character appears
225	    let first_wild = pattern.find(['*', '?', '[']).unwrap_or(pattern.len());
226	
227	    // Base directory is everything up to the last '/' before the first wildcard
228	    let base_end = pattern[..first_wild].rfind('/').map(|i| i + 1).unwrap_or(0);
229	    let base_dir = if base_end > 0 {
230	        PathBuf::from(&pattern[..base_end])
231	    } else {
232	        PathBuf::from(".")
233	    };
234	
235	    if !base_dir.exists() {
236	        return Ok(Vec::new());
237	    }
238	
239	    let rel_pattern = &pattern[base_end..];
240	
241	    // Walk the directory tree and collect all files
242	    let mut all_paths = Vec::new();
243	    walk_dir_recursive(&base_dir, &mut all_paths);
244	
245	    // Match each path against the relative pattern
246	    let mut matches: Vec<PathBuf> = Vec::new();
247	    for path in all_paths {
248	        let rel_path = path
249	            .strip_prefix(&base_dir)
250	            .unwrap_or(&path)
251	            .to_string_lossy()
252	            .replace('\\', "/");
253	
254	        if glob_match_path(rel_pattern, &rel_path) {
255	            matches.push(path);
256	        }
257	    }
258	
259	    matches.sort();
260	    Ok(matches)
261	}
262	
263	fn walk_dir_recursive(dir: &Path, results: &mut Vec<PathBuf>) {
264	    let entries = match std::fs::read_dir(dir) {
265	        Ok(e) => e,
266	        Err(_) => return,
267	    };
268	    for entry in entries.flatten() {
269	        let path = entry.path();
270	        results.push(path.clone());
271	        if path.is_dir() {
272	            walk_dir_recursive(&path, results);
273	        }
274	    }
275	}
276	
277	/// Match a glob pattern against a path string.
278	///
279	/// Both pattern and path use `/` as separator. The pattern may contain
280	/// `*` (matches non-separator chars), `**` (matches across separators),
281	/// and `?` (matches single non-separator char).
282	fn glob_match_path(pattern: &str, path: &str) -> bool {
283	    let pat_parts: Vec<&str> = pattern.split('/').collect();
284	    let path_parts: Vec<&str> = path.split('/').collect();
285	    match_components(&pat_parts, &path_parts)
286	}
287	
288	fn match_components(patterns: &[&str], paths: &[&str]) -> bool {
289	    if patterns.is_empty() {
290	        return paths.is_empty();
291	    }
292	
293	    if patterns[0] == "**" {
294	        // `**` matches zero or more path components
295	        for i in 0..=paths.len() {
296	            if match_components(&patterns[1..], &paths[i..]) {
297	                return true;
298	            }
299	        }
300	        return false;
301	    }
302	
303	    if paths.is_empty() {
304	        return false;
305	    }
306	
307	    // Match first component, then recurse
308	    match_segment(patterns[0], paths[0]) && match_components(&patterns[1..], &paths[1..])
309	}
310	
311	/// Match a single path segment against a glob pattern segment.
312	///
313	/// Handles `*` (any chars) and `?` (single char).
314	fn match_segment(pattern: &str, text: &str) -> bool {
315	    match_bytes(pattern.as_bytes(), text.as_bytes())
316	}
317	
318	fn match_bytes(pattern: &[u8], text: &[u8]) -> bool {
319	    match (pattern.first(), text.first()) {
320	        (None, None) => true,
321	        (Some(b'*'), _) => {
322	            // Try matching zero chars, or advance text by one
323	            match_bytes(&pattern[1..], text)
324	                || (!text.is_empty() && match_bytes(pattern, &text[1..]))
325	        }
326	        (Some(b'?'), Some(_)) => match_bytes(&pattern[1..], &text[1..]),
327	        (Some(&a), Some(&b)) if a == b => match_bytes(&pattern[1..], &text[1..]),
328	        _ => false,
329	    }
330	}
331	
332	#[cfg(test)]
333	mod tests {
334	    use super::*;
335	    use std::fs;
336	    use tempfile::TempDir;
337	
338	    // --- Directory tests ---
339	
340	    #[test]
