// === Atomic file writes ===

/// Write `content` to `path` atomically via a temporary file and rename.
///
/// Prevents readers from observing partially-written data when
/// multiple threads or processes write to the same path concurrently.
pub fn atomic_write(path: &Path, content: &[u8]) -> std::io::Result<()> {
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir)?;
    }

    let mut tmp_name = path.as_os_str().to_os_string();
    let mut rand = [0u8; 8];
    random_bytes(&mut rand);
    tmp_name.push(format!(
        ".tmp{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        rand[0], rand[1], rand[2], rand[3], rand[4], rand[5], rand[6], rand[7],
    ));
    let tmp_path = PathBuf::from(tmp_name);

    std::fs::write(&tmp_path, content)?;

    match std::fs::rename(&tmp_path, path) {
        Ok(()) => Ok(()),
        Err(e) => {
            let _ = std::fs::remove_file(&tmp_path);
            Err(e)
        }
    }
}

