        let matches = glob("/nonexistent/path/*.txt").unwrap();
        assert!(matches.is_empty());
    }

    // --- open_in_browser ---

    #[test]
    fn open_in_browser_does_not_panic() {
        // We can't really test that it opens a browser, but we can ensure
        // the function compiles and the platform detection works.
        // Don't actually call it in tests as it would open a browser.
    }

    // --- Atomic write tests ---

    #[test]
    fn atomic_write_basic() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("test.txt");

        atomic_write(&path, b"hello world").unwrap();

        let content = fs::read_to_string(&path).unwrap();
        assert_eq!(content, "hello world");
    }

    #[test]
    fn atomic_write_overwrites_existing() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("test.txt");

        fs::write(&path, "old content").unwrap();
        atomic_write(&path, b"new content").unwrap();

        let content = fs::read_to_string(&path).unwrap();
        assert_eq!(content, "new content");
    }

    #[test]
    fn atomic_write_no_temp_file_left_behind() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("test.txt");

        atomic_write(&path, b"content").unwrap();

        let entries: Vec<_> = fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .collect();
        assert_eq!(entries.len(), 1, "only the target file should remain");
        assert_eq!(entries[0].file_name(), "test.txt");
    }

    #[test]
    fn atomic_write_concurrent_no_corruption() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("shared.txt");

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let path = path.clone();
                std::thread::spawn(move || {
                    let content = format!("thread-{}-payload-{}", i, "x".repeat(1000));
                    atomic_write(path.as_path(), content.as_bytes()).unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let content = fs::read_to_string(&path).unwrap();
        assert!(
            content.starts_with("thread-"),
            "content should be from one complete write, got: {}",
            &content[..content.len().min(50)]
        );
        assert!(
            content.contains("payload-"),
            "content should be complete, not truncated"
        );
    }
