112	fn apply_workflow_heuristics(
113	    cat: &mut CategoryMatch,
114	    _details: &DiagnosticDetails,
115	    step_ctx: &StepContext<'_>,
116	    workflow_state: &WorkflowState<'_>,
117	) {
118	    match cat.category {
119	        ErrorCategory::ConnectionRefused => {
120	            // If a service-start step already succeeded, the service may have crashed
121	            if has_service_step_succeeded(step_ctx, workflow_state) {
122	                cat.confidence += 0.1;
123	            }
124	        }
125	        ErrorCategory::NotFound => {
126	            // If an install step for same ecosystem already succeeded,
127	            // the issue is likely a wrong package name, not a missing install
128	            if has_install_step_succeeded(step_ctx, workflow_state) {
129	                cat.confidence += 0.1;
130	            }
131	        }
132	        _ => {}
133	    }
134	}
