136	/// Check if a step that starts a service required by the current step
137	/// has already succeeded.
138	pub(super) fn has_service_step_succeeded(
139	    step_ctx: &StepContext<'_>,
140	    workflow_state: &WorkflowState<'_>,
141	) -> bool {
142	    for (name, step) in workflow_state.steps {
143	        if *name == step_ctx.name {
144	            continue;
145	        }
146	        let is_service_step = step.execution.command.contains("start")
147	            || step.execution.command.split_whitespace().any(|w| w == "up");
148	        if is_service_step {
149	            if let Some(status) = workflow_state.outcomes.get(*name) {
150	                if *status == StepStatus::Completed {
151	                    return true;
152	                }
153	            }
154	        }
155	    }
156	    false
157	}
